// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public {
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }
    function testFuzz_property(bytes32 guess, uint256 blocksToAdvance) public {
        vm.assume(blocksToAdvance >= 1 && blocksToAdvance <= 256);
        address alice = makeAddr("alice");
        vm.deal(alice, 2 ether);
        vm.prank(alice);
        c.lockInGuess{value: 1 ether}(guess);
        uint256 lockBlock = block.number + 1;
        vm.roll(lockBlock + 1);
        vm.warp(block.timestamp + lockBlock + 1);
        vm.prank(alice);
        c.settle();
        bool secondSettleSucceeded;
        vm.roll(block.number + blocksToAdvance);
        vm.warp(block.timestamp + blocksToAdvance + 10000);
        vm.prank(alice);
        try c.settle() {
            secondSettleSucceeded = true;
        } catch {
            secondSettleSucceeded = false;
        }
        assertTrue(!secondSettleSucceeded);
    }
}
